      facts: [ntSafetyFact('result id', r.id), ntSafetyFact('specimen', r.specimenId), ntSafetyFact('test', r.testId), ntSafetyFact('critical value', `${r.value == null ? '-' : r.value} ${r.units || ''}`.trim()), ntSafetyFact('flag', r.flag)],
      requireReason: true,
