  var filtered = useMemoOS(() => {
    var needle = q.trim().toLowerCase();
    return [...all].filter(m => !needle || (m.name + ' ' + (m.text || '')).toLowerCase().includes(needle)).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  }, [all, q]);
  var TEMPLATE = `# New mapper
name      = Untitled Mapper
direction = inbound
format    = csv
header    = true
delimiter = ,

# Map source columns to LIS entity fields:
patient.mrn        = MRN
patient.lastName   = LastName
patient.firstName  = FirstName

order.orderNumber  = OrderID
order.testIds      = split(TestCodes, ";")
order.priority     = map(Priority, S=stat, R=routine)
`;
  var startNew = () => {
    if (!hasPermission('EDIT_INTERFACES')) return;
    setEditingId(null);
    setDraft({
      id: 'mapper_' + Date.now().toString(36),
      name: 'Untitled Mapper',
      text: TEMPLATE,
      active: true,
      builtin: false
    });
  };
  var startEdit = m => {
    if (!hasPermission('EDIT_INTERFACES')) return;
    setEditingId(m.id);
    setDraft({
      ...m
    });
  };
  var cancel = () => {
    setEditingId(null);
    setDraft(null);
  };
  var save = async () => {
    if (!hasPermission('EDIT_INTERFACES')) return;
    if (!draft || !draft.text) return;
    var parsed = window.mappers.parse(draft.text);
    var name = parsed.meta && parsed.meta.name || draft.name || 'Untitled';
    if (editingId) {
      var existing = all.find(m => m.id === editingId);
      if (existing) await window.db.put('mappers', {
        ...existing,
        ...draft,
        name,
        updatedAt: Date.now()
      });
    } else {
      await window.db.put('mappers', {
        ...draft,
        name,
        createdAt: Date.now(),
        updatedAt: Date.now()
      });
    }
    cancel();
  };
  var remove = async m => {
    if (!hasPermission('EDIT_INTERFACES')) return;
    if (m.builtin) {
      await safetyNotice({
        tone: 'warning',
        title: 'Mapper delete blocked',
        message: 'Built-in mappers cannot be deleted. Deactivate the mapper instead.',
        facts: [safetyFact('mapper', m.name), safetyFact('id', m.id)]
      });
      return;
    }
    var ask = await safetyConfirm({
      id: 'admin.mapper.delete',
      tone: 'danger',
      title: 'Delete mapper',
      message: 'This removes the mapper script from import/export configuration.',
      facts: [safetyFact('mapper id', m.id), safetyFact('name', m.name), safetyFact('active', m.active !== false ? 'yes' : 'no')],
      entityType: 'mapper',
      entityId: m.id,
      confirmLabel: 'Delete mapper'
    });
    if (!ask.confirmed) return;
    if (!hasPermission('EDIT_INTERFACES')) return;
    var fresh = await window.db.get('mappers', m.id);
    if (!fresh) return;
    await window.db.delete('mappers', m.id);
    if (editingId === m.id) cancel();
  };
  var toggleActive = async m => {
    if (!hasPermission('EDIT_INTERFACES')) return;
    var nextActive = m.active === false;
    var ask = await confirmConfigChange({
      id: nextActive ? 'admin.mapper.activate' : 'admin.mapper.deactivate',
      title: nextActive ? 'Activate mapper' : 'Deactivate mapper',
      message: 'This changes whether the mapper can be used for interface intake.',
      facts: [safetyFact('mapper id', m.id), safetyFact('name', m.name), safetyFact('format', m.format || '-'), safetyFact('next state', nextActive ? 'active' : 'inactive')],
      entityType: 'mapper',
      entityId: m.id,
      confirmLabel: nextActive ? 'Activate mapper' : 'Deactivate mapper'
    });
    if (!ask.confirmed) return;
    if (!hasPermission('EDIT_INTERFACES')) return;
    var fresh = await window.db.get('mappers', m.id);
    if (!fresh) return;
    await window.db.put('mappers', {
      ...fresh,
      active: nextActive
    });
  };
