  if (m == null || !Number.isFinite(m)) return '—';
  if (m < 60) return Math.round(m) + 'm';
  var h = m / 60;
  if (h < 24) return h.toFixed(1).replace(/\.0$/, '') + 'h';
  var d = h / 24;
  return d.toFixed(1).replace(/\.0$/, '') + 'd';
